  }

  if (body.trim()) verified++;
  blocks.push([
    '### ' + c.id + ' ' + c.title,
    'URL: ' + c.url,
    body.trim() ? '원문 본문(실제로 가져온 것):' : '원문 본문: 가져오지 못했습니다. 이 후보는 미확인으로 다룬다.',
    body.trim() ? body : '',
  ].filter(Boolean).join('\n'));
}

